@startuml

class Person {
  + firstName
  + lastName
  + address
}

class Worker extends Person {
  + birthDate
  + skills: string[]
}

class Client extends Person {
  + phoneNumber
  + contactPerson
}

class Machine {
  + serialNumber
  + make
  + model
  + purchaseDate
}

class ProductType {
  + material
  + weight
}

class Product {
  + id
}

class PurchaseOrder {
  + orderNumber
  + dateMade
  + expectedDeliveryDate
  + actualDeliveryDate
}

class OrderLine {
  + quantity
}

Worker "*" -- "*" Machine
Machine "1" -- "*" ProductType
ProductType "1" -- "*" Product
Client "1" -- "*" PurchaseOrder
PurchaseOrder "1" *-- "*" OrderLine
OrderLine "*" -- "1" Product

@enduml

